-- Source-backed Italian spell description overrides; ranks 801-1000.
local _, ns = ...
ns.data = ns.data or {}
ns.data.spellDescriptionOverrides = ns.data.spellDescriptionOverrides or {}

local entries = {
    [370444] = { en = "Health increased by $s1% and damage increased by $s2%.", description = "Salute aumentata del $s1% e danni aumentati del $s2%." },
    [370531] = { en = "Entraps the soul of the dead target, granting you a beneficial effect. This effect lasts for $370552d.", description = "Intrappola l'anima del bersaglio morto, conferendoti un effetto benefico. Dura $370552d." },
    [370575] = { en = "Corrupts your weapon, summoning a copy of it that will aid you in combat for $d.", description = "Corrompe la tua arma ed evoca una sua copia che ti aiuta in combattimento per $d." },
    [370831] = { en = "Affix the bolts to your neck, applying a positive or negative charge at random that grants $s1% increased damage and healing. \r\n\r\nThis effect stacks while near allies who have a similar charge, and deals Nature damage to allies who have an opposite charge.", description = "Applica i dardi al tuo collo, assegnando una carica positiva o negativa casuale che aumenta del $s1% i danni e le cure.\r\n\r\nL'effetto si accumula vicino ad alleati con una carica simile e infligge danni da natura a quelli con una carica opposta." },
    [370832] = { en = "Pierce yourself with the fang, increasing movement speed, attack speed, and cast speed by $s1% for $d.", description = "Trafiggiti con la zanna per aumentare del $s1% la velocità di movimento, d'attacco e di lancio per $d." },
    [398115] = { en = "Take $s3% damage to remove a disease or poison effect from yourself.", description = "Subisci $s3% danni per rimuovere da te un effetto di malattia o veleno." },
    [398117] = { en = "Open the bag of treats and palm it into your target's pocket, increasing the damage of Beasts against this target by $s2.", description = "Apri il sacchetto di leccornie e infilalo nella tasca del bersaglio, aumentando di $s2 i danni che le bestie gli infliggono." },
    [398198] = { en = "Finishing move that increases parry chance. Lasts longer and increases parry chance per combo point:\r\n   1 point  : 10 seconds, 12% Parry\r\n   2 points: 15 seconds, 14% Parry\r\n   3 points: 20 seconds, 16% Parry\r\n   4 points: 25 seconds, 18% Parry\r\n   5 points: 30 seconds, 20% Parry", description = "Mossa finale che aumenta la probabilità di parata. Dura più a lungo e aumenta la probabilità di parata in base ai punti combo:\r\n   1 punto: 10 secondi, 12% di parata\r\n   2 punti: 15 secondi, 14% di parata\r\n   3 punti: 20 secondi, 16% di parata\r\n   4 punti: 25 secondi, 18% di parata\r\n   5 punti: 30 secondi, 20% di parata" },
    [398608] = { en = "Coats a weapon with poison that lasts for 30 minutes.\r\nEach strike has a $h% chance of poisoning the enemy, slowing their movement speed by $3409s1% for $3409d.", description = "Ricopre un'arma di veleno per 30 minuti.\r\nOgni colpo ha una probabilità del $h% di avvelenare il nemico e rallentarne il movimento del $3409s1% per $3409d." },
    [398609] = { en = "Coats a weapon with poison that lasts for 30 minutes.\r\nEach strike has a 30% chance of poisoning the enemy, slowing their movement speed by $3409s1% for $3409d.", description = "Ricopre un'arma di veleno per 30 minuti.\r\nOgni colpo ha una probabilità del 30% di avvelenare il nemico e rallentarne il movimento del $3409s1% per $3409d." },
    [399956] = { en = "Instantly attacks with both weapons for $399960s2% weapon damage plus an additional ${$399960m1*$399960m2/100} with each weapon. Damage increased by $m4% against Poisoned targets. Awards $m1 Combo $LPoint:Points;.", description = "Attacca istantaneamente con entrambe le armi, infliggendo $399960s2% dei danni dell'arma più ${$399960m1*$399960m2/100} con ciascuna. I danni aumentano del $m4% contro i bersagli avvelenati. Assegna $m1 combo $LPoint:Points;." },
    [399965] = { en = "Grants several improvements to your poisons:\r\n\r\nWhen you inflict any other poison on a target, you also inflict Deadly Poison.\r\n\r\nIf your weapon does not have a poison applied, it has a chance to trigger Instant Poison as if Instant Poison were applied.\r\n\r\nDeadly Poison and Instant Poison now gain increased damage from your Attack Power.\r\n\r\nYour Deadly Poison can now be active on targets affected by another Rogue's Deadly Poison.", description = "Migliora i tuoi veleni:\r\n\r\nQuando applichi un altro veleno al bersaglio, applichi anche Veleno Mortale.\r\n\r\nSe l'arma non ha un veleno, può attivare Veleno Istantaneo come se fosse applicato.\r\n\r\nVeleno Mortale e Veleno Istantaneo infliggono più danni in base alla potenza d'attacco.\r\n\r\nVeleno Mortale può essere attivo anche sui bersagli affetti dal Veleno Mortale di un altro Ladro." },
    [399985] = { en = "Teleport behind your target and strike, causing $s3% weapon damage to the target.  Must be stealthed.  Awards $s4 combo $lpoint:points;.", description = "Teletrasportati alle spalle del bersaglio e colpiscilo, infliggendo danni pari al $s3% dei danni dell'arma. Richiede furtività. Assegna $s4 combo $lpoint:points;." },
    [400012] = { en = "Finishing move that increases your Parry chance by $s2% and grants $s4 Attack Power for each point of your defense skill beyond ${$PL*5}. Lasts longer per combo point:\r\n\r\n   1 point  : 14 seconds\r\n   2 points: 18 seconds\r\n   3 points: 22 seconds\r\n   4 points: 26 seconds\r\n   5 points: 30 seconds", description = "Mossa finale che aumenta del $s2% la probabilità di parata e conferisce $s4 potenza d'attacco per ogni punto di Difesa oltre ${$PL*5}. Dura più a lungo in base ai punti combo:\r\n\r\n   1 punto: 14 secondi\r\n   2 punti: 18 secondi\r\n   3 punti: 22 secondi\r\n   4 punti: 26 secondi\r\n   5 punti: 30 secondi" },
    [400016] = { en = "Each time you Dodge or Parry, you gain $400015s1% increased Health, stacking up to $s2 times.", description = "Ogni volta che schivi o pari, la tua salute aumenta del $400015s1%. L'effetto si accumula fino a $s2 volte." },
    [400029] = { en = "Attempts to step through the shadows and reappear behind your enemy and increases movement speed by $406722s1% for $406722d.", description = "Tenta di attraversare le ombre e riapparire alle spalle del nemico, aumentando la velocità di movimento del $406722s1% per $406722d." },
    [400573] = { en = "Blasts the target with energy, dealing Arcane damage. Each time you cast Arcane Blast, the damage of all other spells is increased by $400573s1% and mana cost of Arcane Blast is increased by $400573s2%. Effect stacks up to $400573u times and lasts $400573d.", description = "Colpisce il bersaglio con energia arcana. Ogni volta che lanci Esplosione Arcana, i danni degli altri incantesimi aumentano del $400573s1% e il suo costo in mana del $400573s2%. L'effetto si accumula fino a $400573u volte e dura $400573d." },
    [400586] = { en = "Blasts the target with energy, dealing Arcane damage.  Each time you cast Arcane Blast, the damage of all other Arcane spells is increased by $400573s1% and mana cost of Arcane Blast is increased by $400573s2%.  Effect stacks up to $400573u times and lasts $400573d.", description = "Colpisce il bersaglio con energia arcana. Ogni volta che lanci Esplosione Arcana, i danni degli altri incantesimi arcani aumentano del $400573s1% e il suo costo in mana del $400573s2%. L'effetto si accumula fino a $400573u volte e dura $400573d." },
    [400588] = { en = "Gives your Arcane Blast spell a $m1% chance, and your Fireball, Frostbolt, and Frostfire Bolt spells a ${$m1/2}% chance to reduce the channeled duration of your next Arcane Missiles spell by $400589s1%, reduce the Mana cost by $400589s3%, and missiles fire every ${$m2/10}.1 sec.", description = "Esplosione Arcana ha una probabilità del $m1% e Palla di Fuoco, Dardo di Gelo e Dardo di Fuocogelo una probabilità del ${$m1/2}% di ridurre la durata canalizzata del prossimo Missili Arcani del $400589s1%, il costo in mana del $400589s3% e l'intervallo tra i missili a ${$m2/10}.1 s." },
    [400589] = { en = "Gives your Arcane Blast, Fireball, and Frostbolt spells a chance to reduce the channeled duration of the next Arcane Missiles spell by $400589s1%, reduce the mana cost by $s3%, and missiles fire every ${$400588m2/10}.1 sec.", description = "Esplosione Arcana, Palla di Fuoco e Dardo di Gelo hanno una probabilità di ridurre la durata canalizzata del prossimo Missili Arcani del $400589s1%, il costo in mana del $s3% e l'intervallo tra i missili a ${$400588m2/10}.1 s." },
    [400613] = { en = "The target becomes a Living Bomb, taking ${$<power>*$400613m1/100*4} Fire damage over $d.  After $d or when the spell is dispelled, the target explodes dealing ${$<power>*$400614m1/100} Fire damage to all enemies within $400614a1 yards.\r\n\r\nLiving Bomb benefits from all talents and effects that trigger from or modify Scorch.", description = "Il bersaglio diventa una Bomba Vivente e subisce ${$<power>*$400613m1/100*4} danni da fuoco in $d. Dopo $d o quando viene dissolta, esplode e infligge ${$<power>*$400614m1/100} danni da fuoco ai nemici entro $400614a1 m.\r\n\r\nBomba Vivente beneficia degli effetti che si attivano con o modificano Bruciatura." },
    [400614] = { en = "The target becomes a Living Bomb, taking ${$<power>*$400613m1/100*4} Fire damage over $d.  After $d or when the spell is dispelled, the target explodes dealing ${$<power>*$400614m1/100} Fire damage to all enemies within $400614a1 yards.", description = "Il bersaglio diventa una Bomba Vivente e subisce ${$<power>*$400613m1/100*4} danni da fuoco in $d. Dopo $d o quando viene dissolta, esplode e infligge ${$<power>*$400614m1/100} danni da fuoco ai nemici entro $400614a1 m." },
    [400615] = { en = "Fire Blast will always deal a critical strike, can be cast while casting another spell, and is not affected by the global cooldown, but its cooldown is increased to $s9 sec.", description = "Detonazione di Fuoco infligge sempre un colpo critico, può essere lanciata mentre lanci un altro incantesimo e non è influenzata dal tempo di recupero globale, ma il suo tempo di recupero aumenta a $s9 s." },
    [400624] = { en = "Your non-periodic critical strikes with Fireball, Frostfire Bolt, Fire Blast, and Scorch grant Hot Streak for $400625d. Hot Streak reduces the cast time of Pyroblast by $400625s1%, stacking up to $400625s2 times.", description = "I colpi critici non periodici con Palla di Fuoco, Dardo di Fuocogelo, Detonazione di Fuoco e Bruciatura attivano Serie Rovente per $400625d. Serie Rovente riduce del $400625s1% il tempo di lancio di Pirosfera e si accumula fino a $400625s2 volte." },
    [400647] = { en = "Gives your Chill effects a $s2% chance to grant you the Fingers of Frost effect, which treats your next $m1 $lspell:spells; cast as if the target were Frozen. Lasts $400669d.", description = "Gli effetti di Congelamento hanno una probabilità del $s2% di attivare Dita di Ghiaccio, che fa considerare congelato il bersaglio dei tuoi prossimi $m1 $lspell:spells; incantesimi. Dura $400669d." },
    [400731] = { en = "Your Frost damage spells with chilling effects have a $h% chance to cause your next Fireball, Spellfrost Bolt, Balefire Bolt, or Frostfire Bolt spell to be instant cast and cost no mana.", description = "Gli incantesimi che infliggono danni da gelo e applicano effetti debilitanti hanno una probabilità del $h% di rendere istantaneo e gratuito il tuo prossimo incantesimo Palla di Fuoco, Spellfrost Bolt, Balefire Bolt o Frostfire Bolt." },
    [400735] = { en = "Records the subject's space-time position. $s4% of all Arcane damage done by the caster will be converted to chronomantic healing on each of the caster's current Temporal Beacon targets. This healing is reduced by $s5% on self, and also reduced by $s6% when damage is done by Arcane spells that damage multiple targets.", description = "Registra la posizione spazio-temporale del soggetto. Il $s4% dei danni arcani inflitti dal lanciatore viene convertito in cure cronomantiche per i suoi bersagli affetti da Faro Temporale. Le cure si riducono del $s5% sul lanciatore e del $s6% quando provengono da incantesimi arcani che colpiscono più bersagli." },
    [401462] = { en = "Your current target with your Temporal Beacon instantly heals all damage taken over the last $s1 seconds. Ineffective on targets that did not have a Temporal Beacon $s1 seconds ago.", description = "Il bersaglio attuale del tuo Faro Temporale viene curato istantaneamente di tutti i danni subiti negli ultimi $s1 secondi. Non ha effetto sui bersagli che non erano affetti da Faro Temporale $s1 secondi fa." },
    [401556] = { en = "Summons a spellfire flame that moves toward the target, leaving a trail of spellfire. This trail deals ${$<power>*$401558m1/100} Spellfire damage every second to nearby enemies. Lasts $d.", description = "Evoca una fiamma di focolare magico che si muove verso il bersaglio lasciando una scia. La scia infligge ${$<power>*$401558m1/100} danni da focolare magico ogni secondo ai nemici vicini. Dura $d." },
    [401558] = { en = "Deals ${$<power>*$m1/100} Fire damage every $t1 sec.", description = "Infligge ${$<power>*$m1/100} danni da fuoco ogni $t1 secondi." },
    [401946] = { en = "Heals all of target player's party members within $a1 yards of target player for ${$<healpower>*$m1/100} to ${$<healpower>*$M1/100}.", description = "Cura tutti i membri del gruppo del giocatore bersaglio entro $a1 m di ${$<healpower>*$m1/100}–${$<healpower>*$M1/100}." },
    [401955] = { en = "A word of dark binding that inflicts ${$<damagepower>*$m1/100} to ${$<damagepower>*$M1/100} Shadow damage to the target.  If the target is not killed by Shadow Word: Death, the caster takes damage equal to $m2% of the damage attempted against the target.", description = "Una parola di oscuro vincolo infligge al bersaglio da ${$<damagepower>*$m1/100} a ${$<damagepower>*$M1/100} danni da ombra. Se Parola d'Ombra: Morte non uccide il bersaglio, chi l'ha lanciata subisce danni pari al $m2% dei danni tentati." },
    [401969] = { en = "Your Shadow Word: Pain now also afflicts up to ${$m1-1} additional nearby targets within $s2 yards.", description = "Parola d'Ombra: Dolore affligge anche fino a ${$m1-1} bersagli vicini aggiuntivi entro $s2 m." },
    [401990] = { en = "Crawls through the shadows to the target enemy, and increases damage done by the Shadowfiend by $s2% for $d.", description = "Striscia tra le ombre fino al nemico bersaglio e aumenta del $s2% i danni inflitti dal tuo Ombroservo per $d." },
    [402000] = { en = "Reduces the cooldown on your Power Word: Shield spell by ${$m1/-1000} sec and reduces its mana cost by $s2%.", description = "Riduce di ${$m1/-1000} s il tempo di recupero di Parola del Potere: Scudo e del $s2% il suo costo in mana." },
    [402004] = { en = "Instantly reduces all damage taken by a friendly target by $s1% and increases resistance to Dispel mechanics by $s2% for $d.", description = "Riduce istantaneamente del $s1% tutti i danni subiti da un alleato e aumenta del $s2% la sua resistenza agli effetti di dissoluzione per $d." },
    [402174] = { en = "Launches a volley of holy light at the target, causing $402284s1 Holy damage to an enemy, or $402289s1 healing to an ally, instantly and every $402261t2 sec for $402261d.", description = "Scaglia una raffica di luce sacra contro il bersaglio, infliggendo $402284s1 danni sacri a un nemico oppure curando un alleato di $402289s1, subito e ogni $402261t2 s per $402261d." },
    [402284] = { en = "Dealing $s1 Holy damage every $402261t2 sec.", description = "Infligge $s1 danni sacri ogni $402261t2 s." },
    [402289] = { en = "Healing for $s1 every $402277t2 sec. for $402277d.", description = "Cura di $s1 ogni $402277t2 s per $402277d." },
    [402668] = { en = "Applies your Vampiric Embrace talent to your target, causes ${$<damagepower>*$m2/100*5} Shadow damage over $d to your target, and causes all party members to gain mana equal to $s1% of any Shadow spell damage you deal to the target.", description = "Applica al bersaglio il tuo talento Abbraccio Vampirico e gli infligge ${$<damagepower>*$m2/100*5} danni da ombra in $d. I membri del gruppo ottengono mana pari al $s1% dei danni da ombra che infliggi al bersaglio." },
    [402789] = { en = "Call an eye of the void to fight for you for $d. The eye can cast a variety of curses on your target.", description = "Evoca un occhio del Vuoto che combatte al tuo fianco per $d e può lanciare diverse maledizioni sul bersaglio." },
    [402791] = { en = "Curses the target for $d, reducing Shadow and Arcane resistances by $s1 and increasing Shadow and Arcane damage taken by $s2%.  Only one Curse per Warlock can be active on any one target.", description = "Maledice il bersaglio per $d, riducendone di $s1 le resistenze all'ombra e all'arcano e aumentando del $s2% i danni da ombra e arcani subiti. Ogni Stregone può avere una sola maledizione attiva per bersaglio." },
    [402794] = { en = "Forces the target to speak in Demonic, slowing the casting time of all spells by $s1%.  Only one Curse per Warlock can be active on any one target.  Lasts $d.", description = "Costringe il bersaglio a parlare in Demoniaco e rallenta del $s1% il lancio di tutti gli incantesimi. Ogni Stregone può avere una sola maledizione attiva per bersaglio. Dura $d." },
    [402799] = { en = "Break off splinters of your soul to animate $s1 miniature copies of yourself that attempt to attack your current target with a mace, sword, and axe, reducing the attack speed, attack power, and armor respectively of any target they hit.", description = "Anima $s1 copie in miniatura di te con frammenti della tua anima. Attaccano il bersaglio con mazza, spada e ascia, riducendone rispettivamente velocità d'attacco, potenza d'attacco e armatura." },
    [402911] = { en = "A ferocious strike that deals $s1% weapon damage, but can only be used while Enrage, Berserker Rage, or Bloodrage is active. Each other melee ability used while Enrage, Berserker Rage, or Bloodrage is active reduces Raging Blow's remaining cooldown by $s3 sec.", description = "Colpo furente, che infligge danni pari al $s1% dei danni dell'arma. Utilizzabile solo con Furia, Ira Berserk o Furia Sanguinaria attive. Ogni altra abilità da mischia usata in questi stati riduce di $s3 s il tempo di recupero rimanente di Colpo Furente." },
    [402922] = { en = "Slam is now instant but has a ${$m2/1000} sec cooldown.", description = "Schianto diventa istantaneo, ma ha un tempo di recupero di ${$m2/1000} s." },
    [402927] = { en = "Instantly attack the target causing ${1+$AP*$m3/100} damage and healing you for $s2% of your maximum health.  Only useable within $402975d after you kill a non-trivial enemy.", description = "Attacca istantaneamente il bersaglio, infliggendo ${1+$AP*$m3/100} danni e curandoti del $s2% della salute massima. Utilizzabile solo entro $402975d dall'uccisione di un nemico impegnativo." },
    [403195] = { en = "While you are in Defensive Stance and have a shield equipped, Sunder Armor also deals damage equal to $403196s1% of your equipped weapon's damage per second, increased by $403196s2% per application of Sunder Armor already on the target. Devastate damage deals a high amount of threat while you are in Defensive Stance.", description = "In Assetto Difensivo, con uno scudo equipaggiato, Spacca Armatura infligge danni pari al $403196s1% dei danni al secondo dell'arma, aumentati del $403196s2% per ogni applicazione già presente sul bersaglio. Devastate genera molta minaccia in questo assetto." },
    [403196] = { en = "Sunder Armor also deals $s1% weapon damage, increased by $s2% per application of Sunder Armor already on the target.", description = "Spacca Armatura infligge anche il $s1% dei danni dell'arma, aumentati del $s2% per ogni applicazione già presente sul bersaglio." },
    [403218] = { en = "You generate $s1% more Rage from all damage you deal.", description = "Generi il $s1% di furia in più da tutti i danni che infliggi." },
    [403219] = { en = "Thunder Clap now increases the time between attacks by an additional $s1%, can be used in any stance, deals $s4% increased damage, and deals $s3% increased threat.", description = "Colpo del Tuono aumenta ulteriormente del $s1% l'intervallo tra gli attacchi, è utilizzabile in qualsiasi assetto, infligge il $s4% di danni aggiuntivi e genera il $s3% di minaccia in più." },
    [403228] = { en = "Throw out a hooked chain to restrain the target and pull them toward you. May not be used on enemies higher than level ${$PL+1} or which are marked as boss enemies.", description = "Scaglia una catena uncinata per immobilizzare il bersaglio e trascinarlo verso di te. Non utilizzabile sui nemici di livello superiore a ${$PL+1} o contrassegnati come boss." },
    [403511] = { en = "Increases health drained or damage done by your Drain Life, Drain Soul, and Wrack spells by $m1%.", description = "Aumenta del $m1% la salute prosciugata o i danni inflitti da Prosciugamento Vitale, Prosciugamento dell'Anima e Strazio." },
    [403628] = { en = "Your Shadow Bolt now strikes up to $s1 targets within a chain distance of $s2 yards, but for $s3% reduced damage.", description = "Dardo d'Ombra colpisce fino a $s1 bersagli entro una distanza di rimbalzo di $s2 m, ma infligge il $s3% di danni in meno." },
    [403650] = { en = "Rain of Fire also leaves a Lake of Fire on the ground that increases all Fire damage you deal and your Demon pet deals to affected enemies by $s1%.", description = "Pioggia di Fuoco lascia al suolo un Lago di Fuoco che aumenta del $s1% i danni da fuoco che tu e il tuo demone infliggete ai nemici nell'area." },
    [403666] = { en = "Your Rain of Fire is no longer channeled, but gains a $s5 sec cooldown.", description = "Pioggia di Fuoco non è più canalizzata, ma ha un tempo di recupero di $s5 s." },
    [403668] = { en = "Your Drain Life is no longer channeled, lasts $403677d with a $403677d cooldown, costs $s2% more mana, and heals you for $s1% more each time it deals damage.", description = "Prosciugamento Vitale non è più canalizzato, dura $403677d e ha un tempo di recupero di $403677d; costa il $s2% di mana in più e ti cura del $s1% in più a ogni danno inflitto." },
    [406722] = { en = "Attempts to step through the shadows and reappear behind your enemy and increases movement speed by $s2% for $d.", description = "Tenta di attraversare le ombre e riapparire alle spalle del nemico, aumentando la velocità di movimento del $s2% per $d." },
    [407632] = { en = "Hammer the current target and up to ${$x1-1} additional nearby targets, causing Holy damage to each equal to $s3 times the damage per second of your main hand weapon. Cooldown shared with Crusader Strike.", description = "Colpisce con il martello il bersaglio attuale e fino a ${$x1-1} bersagli vicini aggiuntivi, infliggendo danni sacri pari a $s3 volte i danni al secondo dell'arma principale. Condivide il tempo di recupero con Colpo del Crociato." },
    [407778] = { en = "An instant weapon attack that causes $s1% of weapon damage to up to ${$i-1} enemies within $a3 yards.  The Divine Storm heals up to 3 party or raid members totaling $s2% of the damage caused.", description = "Attacco istantaneo che infligge il $s1% dei danni dell'arma a un massimo di ${$i-1} nemici entro $a3 m. Tempesta Divina cura fino a 3 membri del gruppo o dell'incursione per un totale pari al $s2% dei danni inflitti." },
    [407989] = { en = "Finishing move that increases physical damage done by $s1%.  Lasts longer per combo point:\r\n   1 point  : 14 seconds\r\n   2 points: 19 seconds\r\n   3 points: 24 seconds\r\n   4 points: 29 seconds\r\n   5 points: 34 seconds", description = "Mossa finale che aumenta dell'$s1% i danni fisici inflitti. Dura più a lungo in base ai punti combo:\r\n   1 punto: 14 s\r\n   2 punti: 19 s\r\n   3 punti: 24 s\r\n   4 punti: 29 s\r\n   5 punti: 34 s" },
    [408024] = { en = "When activated, this grants you $408025s1% of your maximum health and increases all non-Physical healing you deal by $s1% for $d. After the effect expires, the health is lost. Useable in all forms except Moonkin Form.\r\n\r\nIn addition, you regenerate $417051s2 rage every time you dodge while in Bear Form or Dire Bear Form, $417051s3 energy while in Cat Form, or $417051s4% of your maximum mana while in any other form.", description = "Quando attivata, conferisce il $408025s1% della salute massima e aumenta del $s1% le cure non fisiche inflitte per $d. Al termine dell'effetto, la salute aggiuntiva si perde. Utilizzabile in tutte le forme tranne Forma di Lunagufo.\r\n\r\nIn Forma d'Orso o Forma d'Orso Dire rigeneri $417051s2 furia a ogni schivata, in Forma Felina $417051s3 energia e nelle altre forme il $417051s4% della mana massima." },
    [408247] = { en = "Heals a friendly target for ${$m1/100*$<healpower>} to ${$M1/100*$<healpower>}. Heals for an additional 20% if you have a Rejuvenation, Regrowth, Lifebloom, or Wild Growth effect active on the target. This spell benefits from and triggers all effects associated with Healing Touch or Regrowth.", description = "Cura un alleato di ${$m1/100*$<healpower>}–${$M1/100*$<healpower>}. La cura aumenta del 20% se il bersaglio è affetto da Rinvigorimento, Ricrescita, Fioritura Vitale o Crescita Selvaggia. Beneficia e attiva gli effetti associati a Tocco Curativo o Ricrescita." },
    [408307] = { en = "Increases your healing power by $s2% of your Nature spell damage for $d.", description = "Aumenta le cure del $s2% della potenza degli incantesimi di natura per $d." },
    [408309] = { en = "Increases your spell damage by $s2% of the difference between your healing power and spell damage. Lasts $d.", description = "Aumenta i danni degli incantesimi del $s2% della differenza tra la potenza di cura e quella degli incantesimi. Dura $d." },
    [408341] = { en = "Instantly inflicts $8349s1 fire damage to enemies within $8349a1 yd of your active Fire totem.", description = "Infligge istantaneamente $8349s1 danni da fuoco ai nemici entro $8349a1 m dal totem del fuoco attivo." },
    [408342] = { en = "Instantly inflicts $8502s1 fire damage to enemies within $8502a1 yd of your active Fire totem.", description = "Infligge istantaneamente $8502s1 danni da fuoco ai nemici entro $8502a1 m dal totem del fuoco attivo." },
    [408343] = { en = "Instantly inflicts $8503s1 fire damage to enemies within $8503a1 yd of your active Fire totem.", description = "Infligge istantaneamente $8503s1 danni da fuoco ai nemici entro $8503a1 m dal totem del fuoco attivo." },
    [408344] = { en = "Instantly inflicts $11306s1 fire damage to enemies within $11306a1 yd of your active Fire totem.", description = "Infligge istantaneamente $11306s1 danni da fuoco ai nemici entro $11306a1 m dal totem del fuoco attivo." },
    [408345] = { en = "Instantly inflicts $11307s1 fire damage to enemies within $11307a1 yd of your active Fire totem.", description = "Infligge istantaneamente $11307s1 danni da fuoco ai nemici entro $11307a1 m dal totem del fuoco attivo." },
    [408496] = { en = "Increases your chance to hit with both spells and melee attacks by $s1% while dual wielding, your Stormstrike ability now hits with both weapons while dual wielding, and increases the damage done by your offhand weapon by $s3%.", description = "Impugnando due armi, aumenta del $s1% la probabilità di colpire con incantesimi e attacchi in mischia; Assalto della Tempesta colpisce con entrambe le armi e i danni dell'arma secondaria aumentano del $s3%." },
    [408498] = { en = "When you deal damage with a melee attack, you have a chance to reduce the cast time and Mana cost of your next Lightning Bolt spell by $m1%. Stacks up to $s3 times. Lasts $408505d.", description = "Quando infliggi danni con un attacco in mischia, hai una probabilità di ridurre del $m1% il tempo di lancio e il costo in mana del tuo prossimo Dardo Fulminante. Si accumula fino a $s3 volte. Dura $408505d." },
    [408510] = { en = "The caster is surrounded by $n globes of water. When a spell, melee, or ranged attack hits the caster or when one of the caster's healing spells gets a critical result, $408511s1% of maximum mana is restored to the caster, expending one water globe. Only one globe will activate every few seconds.  Lasts $d.\r\n\r\nOnly one Elemental Shield can be active on the Shaman at any one time.", description = "Chi lancia l'incantesimo è circondato da $n globi d'acqua. Quando viene colpito da un incantesimo o da un attacco in mischia o a distanza, oppure quando una sua cura è critica, recupera il $408511s1% della mana massima consumando un globo. Può attivarsi un solo globo ogni pochi secondi. Dura $d.\r\n\r\nLo Scudo Elementale può essere attivo sullo Sciamano in una sola variante alla volta." },
    [408525] = { en = "Increases armor by $s1% of your shield's Armor value for $d, stacking up to $u times.", description = "Aumenta l'armatura del $s1% del valore dello scudo per $d. Si accumula fino a $u volte." },
    [408696] = { en = "Infuses the target with the spirit of an alpha wolf, increasing all threat generated by the target by $s1% for $d. Limit 1 target. If cast on a target other than self, the Shaman also gains Loyal Beta, increasing Physical damage done by $443320s1% and reducing all threat generated by $443320s2% for $d. A target cannot have both Spirit of the Alpha and Loyal Beta at the same time.", description = "Infondi nel bersaglio lo spirito di un lupo alfa, aumentando del $s1% la minaccia generata per $d. Limite: 1 bersaglio. Se lanciato su un alleato, lo Sciamano ottiene anche Beta Fedele, che aumenta del $443320s1% i danni fisici e riduce del $443320s2% la minaccia generata per $d. Non è possibile avere contemporaneamente Spirito dell'Alfa e Beta Fedele." },
    [409073] = { en = "Your melee attacks generate ${$409073m1/10} Rage.", description = "Gli attacchi in mischia generano ${$409073m1/10} furia." },
    [409324] = { en = "For the next $d, $s1% of your damage is converted to healing on up to 3 nearby party members, and $s2% of your healing is converted to damage on your most recent Flame Shock target.", description = "Per $d, il $s1% dei danni inflitti viene convertito in cure per un massimo di 3 membri del gruppo vicini, mentre il $s2% delle cure diventa danno contro il bersaglio più recente della tua Folgore del Fuoco." },
    [409428] = { en = "Increases your critical strike chance by $s1%, and reduces the Mana cost of all your Shot abilities by $s2%.", description = "Aumenta del $s1% la probabilità di colpo critico e riduce del $s2% il costo in mana di tutti gli incantesimi Tiro." },
    [409504] = { en = "Your melee and ranged criticals increase your attack power by $409507s1% of your current Agility for $409507d.", description = "I colpi critici in mischia e a distanza aumentano la potenza d'attacco del $409507s1% dell'Agilità attuale per $409507d." },
    [409507] = { en = "Your ranged criticals increase your attack power by $409507s1% of your Agility for $409507d.", description = "I colpi critici a distanza aumentano la potenza d'attacco del $409507s1% dell'Agilità per $409507d." },
    [409580] = { en = "The hunter invokes the heart of a lion, increasing total stats by $409583s1% and Attack Power by $409583s2 for all nearby allies, and increasing total stats for the Hunter by an additional $409580s1%.", description = "Il cacciatore invoca il cuore del leone: le statistiche totali degli alleati vicini aumentano del $409583s1%, la loro potenza d'attacco di $409583s2 e le statistiche del cacciatore aumentano ulteriormente del $409580s1%." },
    [409583] = { en = "The hunter invokes the heart of a lion, increasing total stats by $409583s1% for all nearby allies, and increasing total stats for the Hunter by an additional $409580s1%.", description = "Il cacciatore invoca il cuore del leone: le statistiche totali degli alleati vicini aumentano del $409583s1% e quelle del cacciatore aumentano ulteriormente del $409580s1%." },
    [409687] = { en = "Increases the damage done by your offhand weapon by $s1% and causes your Raptor Strike to strike with both weapons when you are dual-wielding.", description = "Aumenta del $s1% i danni dell'arma secondaria e fa sì che Colpo del Raptor colpisca con entrambe le armi quando ne impugni due." },
    [410156] = { en = "Gives you an extra attack.  In addition, the next 2 sources of Nature damage dealt to the target are increased by $17364s2%.  Lasts $17364d.", description = "Conferisce un attacco aggiuntivo. Le successive 2 fonti di danni da natura inflitti al bersaglio aumentano inoltre del $17364s2%. Dura $17364d." },
    [410176] = { en = "Charge to a target within 13 yards and bash the target's skull, interrupting spellcasting and preventing any spell in that school from being cast for $414621d. Shares a cooldown with Feral Charge.", description = "Caricati contro un bersaglio entro 13 m e colpiscilo alla testa, interrompendo il lancio e impedendo di lanciare incantesimi di quella scuola per $414621d. Condivide il tempo di recupero con Carica Ferina." },
    [411115] = { en = "Reduces the chance you'll be critically hit by melee attacks by $s2% and reduces all damage taken by $s1%. Damage taken reduced by an additional $411124s1% while in Bear Form or Dire Bear Form.", description = "Riduce del $s2% la probabilità di subire colpi critici in mischia e del $s1% tutti i danni subiti. In Forma d'Orso o Forma d'Orso Dire, i danni subiti si riducono ulteriormente del $411124s1%." },
    [411128] = { en = "Swipe nearby enemies, inflicting $s1% weapon damage and generating $s2 combo $lpoint:points; on your current target.", description = "Colpisce i nemici vicini, infliggendo il $s1% dei danni dell'arma e generando $s2 combo $lpoint:points; sul bersaglio attuale." },
    [411624] = { en = "Begins taming a beast to be your companion.  Your armor is reduced by $1515s3% while you focus on taming the beast for $1515d.  If you lose the beast's attention for any reason, the taming process will fail.  Once tamed, the beast will be very unhappy and disloyal.  Try feeding the pet immediately to make it happy.", description = "Inizi ad addomesticare una bestia per farla diventare la tua compagna. L'armatura si riduce del $1515s3% mentre ti concentri per $1515d. Se perdi l'attenzione della bestia, il processo fallisce. Una volta addomesticata, sarà infelice e sleale. Prova a darle subito da mangiare per renderla felice." },
    [412019] = { en = "Each time the target takes damage they gain a Sacred Shield, absorbing ${$412018m1*$<healpower>/100} damage and increasing the Paladin's chance to critically hit with Flash of Light by $412018s2% for up to $412018d.  In addition, causes your Flash of Light to heal targets with Sacred Shield for an additional $s3% over $412020d. They cannot gain this effect more than once every $s2 sec.  Lasts $d.  This spell cannot be on more than one target at any one time.", description = "Quando il bersaglio subisce danni, ottiene uno Scudo Sacro che assorbe ${$412018m1*$<healpower>/100} e aumenta del $412018s2% la probabilità di colpo critico del paladino con Lampo di Luce per $412018d. Lampo di Luce cura inoltre il bersaglio di un ulteriore $s3% in $412020d. L'effetto può attivarsi solo ogni $s2 s. Dura $d e può essere attivo su un solo bersaglio." },
    [412113] = { en = "Removes $m1 Curse and $m2 harmful Magic effect from a friendly target.", description = "Rimuove $m1 maledizione e $m2 effetti magici dannosi da un alleato." },
    [412286] = { en = "Increases your spell critical strike chance with all spells by $s1%, but your non-periodic spell critical strikes now have an additional mana cost of $s2% of your base mana.", description = "Aumenta del $s1% la probabilità di colpo critico di tutti gli incantesimi, ma i colpi critici non periodici costano mana aggiuntiva pari al $s2% della mana base." },
    [412322] = { en = "Increases critical strike damage bonus of all spells by $s1%.", description = "Aumenta del $s1% il bonus ai danni da colpo critico di tutti gli incantesimi." },
    [412324] = { en = "You deal $s1% more damage while you have more than $s2% mana. While below $s3% mana $s4% of your mana regeneration continues while casting.", description = "Infliggi il $s1% di danni in più quando hai più del $s2% di mana. Sotto il $s3% di mana, durante il lancio rigeneri il $s4% della mana normale." },
    [412326] = { en = "Increases all spell damage done by $s1%.", description = "Aumenta del $s1% tutti i danni inflitti dagli incantesimi." },
    [412513] = { en = "An aggressive stance that increases damage while you are wearing a shield by $413479s1% and increases block chance by $413479s2%, but reduces armor by $413476s1% and threat generated by $413476s2%. In addition, you gain $s2% increased Rage when your auto-attack damages an enemy not targeting you.\r\n\r\nWhile wearing a shield in Gladiator Stance, you may use all abilities that are restricted to other stances.", description = "Assetto aggressivo: aumenta del $413479s1% i danni inflitti con uno scudo e del $413479s2% la probabilità di blocco, ma riduce del $413476s1% l'armatura e del $413476s2% la minaccia. Gli attacchi automatici contro un nemico che non ti sta bersagliando generano il $s2% di furia in più.\r\n\r\nCon uno scudo equipaggiato in Assetto Gladiatore puoi usare tutte le abilità riservate agli altri assetti." },
    [412532] = { en = "Launches a bolt of spellfrost at the enemy, causing ${$<power>*$m2/100*$<frostdamage>} to ${$<power>*$M2/100*$<frostdamage>} Spellfrost damage and slowing movement speed by $s1% for $d. This spell will be checked against the lower of the target's Frost and Arcane resists and counts as both Frost and Arcane damage.", description = "Scaglia un dardo di gelo arcano contro il nemico, infliggendo da ${$<power>*$m2/100*$<frostdamage>} a ${$<power>*$M2/100*$<frostdamage>} danni da gelo arcano e rallentandone del $s1% la velocità per $d. Viene contrastato usando la minore tra le resistenze a gelo e arcano del bersaglio e conta come danno di entrambe le scuole." },
    [412545] = { en = "Deals Fire damage every $t sec.", description = "Infligge danni da fuoco ogni $t s." },
    [412727] = { en = "Increases the critical strike chance of all attacks for you and your summoned Demon by $m1% while the Demon is active.", description = "Aumenta del $m1% la probabilità di colpo critico dei tuoi attacchi e di quelli del demone evocato mentre è attivo." },
    [412732] = { en = "Increases your spell damage and your Demon pet's spell damage by up to $s1% of your level while you have a summoned Demon pet active.", description = "Con un demone evocato attivo, aumenta i danni dei tuoi incantesimi e del famiglio demone fino al $s1% del tuo livello." },
    [412751] = { en = "Increases the critical strike chance of your Conflagrate spell by $m2%.", description = "Aumenta del $m2% la probabilità di colpo critico di Conflagrazione." },
    [412787] = { en = "Choke your enemy with a surge of Shadowy energy that deals $s1 damage, interrupts spellcasting, and prevents any spell in that school from being cast for $d.", description = "Soffoca il nemico con un'ondata di energia d'ombra che infligge $s1 danni, interrompe il lancio e impedisce di lanciare incantesimi di quella scuola per $d." },
    [412788] = { en = "Charge an enemy and stun it for $7922d.  Cannot be used in combat.", description = "Caricati contro un nemico e stordiscilo per $7922d. Non utilizzabile in combattimento." },
    [412790] = { en = "Leap through the air and slam down on all enemies within $a2 yards of the target area, causing $s2 Shadow damage and Stunning them for $d.", description = "Balza in aria e piomba sui nemici entro $a2 m dall'area bersaglio, infliggendo $s2 danni da ombra e stordendoli per $d." },
    [412798] = { en = "You and your demon pet gain dodge chance equal to $s1% of your spell critical strike chance each time you deal a critical strike to an enemy, and also both regain $412800s2% of maximum mana.", description = "Quando infliggi un colpo critico a un nemico, tu e il tuo demone ottenete una probabilità di schivata pari al $s1% della probabilità di colpo critico degli incantesimi e recuperate il $412800s2% della mana massima." },
    [413248] = { en = "Healing with Flash Heal reduces the cast time of your next Lesser Heal, Heal, Greater Heal, or Prayer of Healing by $413247s1% for $413247d, stacking up to $413247u times.", description = "Le cure con Guarigione Rapida riducono del $413247s1% per $413247d il tempo di lancio del tuo prossimo Guarigione Inferiore, Guarigione, Guarigione Superiore o Preghiera di Cura. Si accumula fino a $413247u volte." },
    [413260] = { en = "Causes an explosion of shadow magic around the enemy target, causing $s1 Shadow damage every 1 sec for $48045d to all enemies within $a1 yards around the target.", description = "Provoca un'esplosione di magia d'ombra intorno al nemico, infliggendo $s1 danni da ombra ogni secondo per $48045d a tutti i nemici entro $a1 m." },
    [413404] = { en = "While dual-wielding, your movement speed is increased by $430472s2% and you gain $461470s1% attack speed each time your melee auto-attack strikes the same target as your previous auto-attack, stacking up to $461470u times. Lasts $461470d or until your auto-attack strikes a different target.", description = "Impugnando due armi, la velocità di movimento aumenta del $430472s2% e la velocità d'attacco del $461470s1% quando gli attacchi automatici colpiscono lo stesso bersaglio consecutivamente. Si accumula fino a $461470u volte. Dura $461470d o finché non colpisci un altro bersaglio." },
    [413685] = { en = "Your connection to the Light has been damaged. All Holy healing you deal decreased by $s2%, but all non-Holy damage you deal increased by $s1%.", description = "Il legame con la Luce è danneggiato: le cure sacre fornite si riducono del $s2%, ma i danni non sacri inflitti aumentano del $s1%." },
    [414621] = { en = "You bash the target's skull, interrupting spellcasting and preventing any spell in that school from being cast for $d.", description = "Colpisci il bersaglio alla testa, interrompendo il lancio e impedendo di lanciare incantesimi di quella scuola per $d." },
    [414673] = { en = "Reduces the global cooldown by ${$m1/-1000}.1 seconds on your Rejuvenation, Swiftmend, and Wild Growth spells.", description = "Riduce di ${$m1/-1000}.1 s il tempo di recupero globale di Rinvigorimento, Rinvigorimento Rapido e Crescita Selvaggia." },
    [414677] = { en = "When you critically heal your target with any non-periodic healing spell you plant a Living Seed on the target for $s1% of the amount healed. The Living Seed will bloom the next time the target takes damage or receives non-periodic healing. Lasts $414680d.", description = "Quando curi criticamente il bersaglio con un incantesimo non periodico, pianti un Seme Vivente pari al $s1% delle cure fornite. Germoglia la volta successiva che il bersaglio subisce danni o riceve cure non periodiche. Dura $414680d." },
    [414799] = { en = "Reduces the mana cost of Wrath by $s1% and each time you deal damage with Wrath you have a $h% chance for your next cast of Healing Touch within $414800d to be instant and castable in any shapeshift form. Allows Wrath to be cast while in Tree of Life form.", description = "Riduce del $s1% il costo in mana di Ira. Quando infliggi danni con Ira, hai una probabilità del $h% di rendere istantaneo il prossimo Tocco Curativo entro $414800d e di poterlo lanciare in qualsiasi forma. Consente di lanciare Ira in Forma dell'Albero della Vita." },
    [415059] = { en = "You gain $415058m1% of your maximum mana every $415058t1 sec for $415058d after Blocking a melee attack. This effect is cancelled by casting Flash of Light, Holy Light, or Holy Shock.", description = "Dopo aver bloccato un attacco in mischia, ottieni il $415058m1% della mana massima ogni $415058t1 s per $415058d. L'effetto si annulla lanciando Lampo di Luce, Luce Sacra o Folgore Sacra." },
    [415076] = { en = "Exorcism can now be cast on any target and has $415068s2% increased critical strike chance against Undead and Demons.", description = "Esorcismo può essere lanciato su qualsiasi bersaglio e ha una probabilità di colpo critico aumentata del $415068s2% contro Non Morti e Demoni." },
    [415231] = { en = "Your Flame Shock now strikes up to $s1 targets, gains ${$m5/1000} sec increased duration, and deals $s3% increased damage. In addition, while you have Flametongue Weapon imbued on your main hand equipped weapon, you gain increased spell damage equal to $s7% of your Intellect.", description = "Folgore del Fuoco colpisce fino a $s1 bersagli, dura ${$m5/1000} s in più e infligge il $s3% di danni aggiuntivi. Con un'arma imbevuta di Lingua di Fuoco nella mano principale, la potenza degli incantesimi aumenta di un valore pari al $s7% dell'Intelletto." },
    [415233] = { en = "Turns the Shaman into a Ghost Wolf, increasing speed by $s2% and decreasing all damage taken by $s3%.", description = "Trasforma lo Sciamano in un Lupo Spettrale, aumentandone la velocità del $s2% e riducendo del $s3% i danni subiti." },
    [415236] = { en = "Selects the area $415242a1 yards around target player, and heals all of target player's party members within that area for ${$<healpower>*$415242m1/100} every second.", description = "Seleziona l'area entro $415242a1 m dal giocatore bersaglio e cura ogni secondo tutti i membri del suo gruppo nell'area di ${$<healpower>*$415242m1/100}." },
    [415242] = { en = "Heals up to 5 friendly party or raid members within $a1 yards of the target for ${$<healpower>*$m1/100}.", description = "Cura fino a 5 alleati del gruppo o dell'incursione entro $a1 m di ${$<healpower>*$m1/100}." },
    [415352] = { en = "Your Raptor Strike is now instant, and Mongoose Bite and Raptor Strike have a $s3% chance on each attack to reset the cooldowns of Mongoose Bite and Raptor Strike.", description = "Colpo del Raptor diventa istantaneo; Morsi di Mangusta e Colpo del Raptor hanno una probabilità del $s3% a ogni attacco di azzerare i rispettivi tempi di recupero." },
    [415399] = { en = "When you have not moved for the last 1 sec, you have a $m1% chance to gain Sniper's Aim, stacking up to $415401u times. Sniper's Aim increases the critical strike chance of your Shot abilities by $415401s1%.", description = "Se non ti muovi per 1 s, hai una probabilità del $m1% di ottenere Mira di Precisione, fino a $415401u accumuli. Aumenta del $415401s1% la probabilità di colpo critico degli incantesimi Tiro." },
    [415407] = { en = "Increases the damage of your next Shot ability by $s1%.", description = "Aumenta del $s1% i danni del tuo prossimo incantesimo Tiro." },
    [415413] = { en = "Each time you place a trap, your next Shot (except Scatter Shot) ability within $415414d costs no mana and does not incur a cooldown.", description = "Ogni volta che piazzi una trappola, il prossimo incantesimo Tiro (tranne Tiro dirompente) entro $415414d non costa mana e non ha tempo di recupero." },
    [415423] = { en = "The hunter takes on the aspect of the viper, causing your ranged and melee auto attacks to regenerate mana but reducing your total damage done by $s2%.  In addition, you gain $s1% of maximum mana every $t sec.  Mana gained is based on the speed of your weapon. Only one Aspect can be active at a time.", description = "Il cacciatore assume l'Aspetto della Vipera: gli attacchi automatici in mischia e a distanza rigenerano mana, ma i danni totali inflitti si riducono del $s2%. Rigeneri inoltre il $s1% della mana massima ogni $t s; la quantità dipende dalla velocità dell'arma. Un solo Aspetto può essere attivo alla volta." },
    [415428] = { en = "Increases your chance to dodge by $s1% and your pet's chance to dodge by $s2%. In addition, reduces the cooldown of your Flanking Strike ability by $s3%.", description = "Aumenta del $s1% la probabilità di schivata tua e del $s2% quella del famiglio. Riduce inoltre del $s3% il tempo di recupero di Assalto Laterale." },
    [415813] = { en = "Your Ghost Wolf ability can now be used indoors, and reduces all damage you take by $415233s3% while active.", description = "Lupo Spettrale può essere usato al chiuso e riduce del $415233s3% i danni subiti mentre è attivo." },
    [417046] = { en = "Tiger's Fury now instantly grants you $s1 Energy.", description = "Furia della Tigre ti conferisce istantaneamente $s1 energia." },
    [417051] = { en = "Increases your dodge chance by $m1%, and gives you a $m2% chance to gain ${$417053m1/10} Rage each time you dodge.", description = "Aumenta del $m1% la probabilità di schivata e conferisce una probabilità del $m2% di ottenere ${$417053m1/10} furia a ogni schivata." },
    [417135] = { en = "Increases the damage done by your Hurricane by $s1%, it no longer has a cooldown, and its mana cost is reduced by $s4%.", description = "Aumenta del $s1% i danni inflitti da Uragano, che non ha più tempo di recupero e costa il $s4% di mana in meno." },
    [417145] = { en = "Striking a target with Lacerate, Swipe, or Maul has a $h% chance to reset the cooldown on Mangle (Bear) and grant ${$446699m1/10}  Rage. Striking a target with Mangle (Cat) or Shred has a $s1% chance to reset the cooldown on Tiger's Fury.", description = "Colpire con Lacerare, Spazzata o Maul ha una probabilità del $h% di azzerare il tempo di recupero di Mangle (Bear) e conferire ${$446699m1/10} furia. Colpire con Mangle (Cat) o Sventramento ha una probabilità del $s1% di azzerare il tempo di recupero di Furia della Tigre." },
    [417147] = { en = "Heals all party or raid members within $417148a1 yards of the selected area for ${$<healpower>*$417148m1/100} every $417147t1 sec for $d.", description = "Cura i membri del gruppo o dell'incursione entro $417148a1 m dall'area selezionata di ${$<healpower>*$417148m1/100} ogni $417147t1 s per $d." },
    [417148] = { en = "Heals all party members within $a1 yards of the target for ${$<healpower>*$m1/100}.", description = "Cura i membri del gruppo entro $a1 m dal bersaglio di ${$<healpower>*$m1/100}." },
    [417149] = { en = "Your Swiftmend now also causes Efflorescence, healing all party members within $417148a1 yards of the Swiftmend target's location for ${$<healpower>*$417148m1/100} every $417147t2 sec for $417147d.", description = "Rinvigorimento Rapido provoca anche Fioritura, curando i membri del gruppo entro $417148a1 m dalla posizione del bersaglio di ${$<healpower>*$417148m1/100} ogni $417147t2 s per $417147d." },
    [417440] = { en = "Strikes all nearby enemies, dealing ${$m1*$<damagepower>/100+0.092*$AP} Bleed damage and an additional ${$417441m1*$<damagepower>/100*5+0.125*$AP} Bleed damage over $417441d. When applied from Bear Form, this effect can stack up to $417441u times.", description = "Colpisce tutti i nemici vicini, infliggendo ${$m1*$<damagepower>/100+0.092*$AP} danni da sanguinamento e altri ${$417441m1*$<damagepower>/100*5+0.125*$AP} in $417441d. In Forma d'Orso, si accumula fino a $417441u volte." },
    [417448] = { en = "Strikes all nearby enemies, dealing ${$m1*$<damagepower>/100+0.104*$AP} Bleed damage and an additional ${$m2*$<damagepower>/100*5+0.0661*5*$AP} Bleed damage over $d. Awards $417450s1 combo $lpoint:points;.", description = "Colpisce tutti i nemici vicini, infliggendo ${$m1*$<damagepower>/100+0.104*$AP} danni da sanguinamento e altri ${$m2*$<damagepower>/100*5+0.0661*5*$AP} in $d. Assegna $417450s1 combo $lpoint:points;." },
    [423299] = { en = "Increases damage done to Beasts with physical attacks by $s1. ", description = "Aumenta di $s1 i danni fisici inflitti agli animali." },
    [423300] = { en = "M'grrgl will accompany you for $d1, providing minor protection against shadow.", description = "M'grrgl ti accompagna per $d1 e ti protegge in parte dall'ombra." },
    [423304] = { en = "Leech life from your victim, healing for $s1 damage.", description = "Prosciuga la vita della vittima e cura di $s1 danni." },
    [424785] = { en = "Viciously slash an enemy for $s2% weapon damage, and cause the target to bleed for ${$AP*$m4/100} damage every $t4 sec for $d, stacking up to $u times. Each stack also increases damage done by your Saber Slash and Sinister Strike by $s5%. Awards $s3 combo $lpoint:points;.\r\n\r\nSaber Slash benefits from all talents and effects that trigger from or modify Sinister Strike.", description = "Ferisce brutalmente un nemico, infliggendo il $s2% dei danni dell'arma e facendolo sanguinare per ${$AP*$m4/100} danni ogni $t4 s per $d. Si accumula fino a $u volte; ogni accumulo aumenta del $s5% i danni di Fendente con Sciabola e Colpo Funesto. Assegna $s3 combo $lpoint:points;.\r\n\r\nFendente con Sciabola beneficia degli effetti che si attivano con o modificano Colpo Funesto." },
    [424799] = { en = "Instantly attack with your off-hand weapon to deal normal off-hand weapon damage with a 100% chance to apply the poison from your off-hand weapon to the target. Slower weapons require more energy. Awards $s2 combo $lpoint:points;.\r\n\r\nShiv benefits from all talents and effects that trigger from or modify Sinister Strike.", description = "Attacca istantaneamente con l'arma secondaria, infliggendo i normali danni e applicando sicuramente il veleno presente su di essa. Le armi più lente richiedono più energia. Assegna $s2 combo $lpoint:points;.\r\n\r\nShiv beneficia degli effetti che si attivano con o modificano Colpo Funesto." },
    [425121] = { en = "Hastens your spellcasting, increasing spell casting speed by $s1% and reduces the pushback suffered from damaging attacks while casting by $s2%. Lasts $d.", description = "Accelera il lancio degli incantesimi, aumentando del $s1% la velocità di lancio e riducendo del $s2% il contraccolpo subito dagli attacchi durante il lancio. Dura $d." },
    [425198] = { en = "Mind Flay and Mind Blast deal $s1% increased damage to targets afflicted with your Shadow Word: Pain.", description = "Tortura Mentale ed Esplosione Mentale infliggono il $s1% di danni in più ai bersagli affetti da Parola d'Ombra: Dolore." },
    [425204] = { en = "Afflicts the target with a disease that causes ${$<damagepower>*$m1/100*6} Shadow damage over $d.", description = "Affligge il bersaglio con una malattia che infligge ${$<damagepower>*$m1/100*6} danni da ombra in $d." },
    [425207] = { en = "Summons a holy barrier to protect all party members at the target location for $d, reducing all damage taken by $425205s1% and preventing damage from delaying spellcasting. ", description = "Evoca una barriera sacra che protegge per $d i membri del gruppo nella posizione bersaglio, riducendo del $425205s1% i danni subiti e impedendo ai danni di ritardare il lancio degli incantesimi." },
    [425280] = { en = "Your heals from Flash Heal, Binding Heal, Lesser Heal, Heal, Greater Heal, and Penance gain $m1% increased critical strike chance when cast on targets with Weakened Soul, and reduce the remaining duration of Weakened Soul on their target by ${$m2/-1000} sec.", description = "Le cure di Guarigione Rapida, Legame Curativo, Guarigione Inferiore, Guarigione, Guarigione Superiore e Penitenza hanno una probabilità di colpo critico aumentata del $m1% sui bersagli con Anima Indebolita e ne riducono la durata rimanente di ${$m2/-1000} s." },
    [425284] = { en = "Activate to become the Spirit of Redemption for $d. While in this form, you can cast any healing spell free of cost, but you cannot move, attack, be attacked, or be targeted by any spells or effects. Requires Spirit of Redemption talent to activate, and you will no longer enter Spirit of Redemption  upon dying.", description = "Attiva per diventare lo Spirito della Redenzione per $d. In questa forma puoi lanciare gratuitamente incantesimi di cura, ma non puoi muoverti, attaccare, essere attaccato o bersagliato. Richiede il talento Spirito della Redenzione; alla morte non entrerai più automaticamente in questa forma." },
    [425294] = { en = "You disperse into pure Shadow energy, reducing all damage taken by $s1%.  You are unable to attack or cast spells, but you regenerate $s2% mana every $t2 sec for $d. Dispersion can be cast while stunned, feared or silenced and clears all snare and movement impairing effects when cast, and makes you immune to them while dispersed.", description = "Ti disperdi in pura energia d'ombra, riducendo del $s1% i danni subiti. Non puoi attaccare né lanciare incantesimi, ma rigeneri il $s2% di mana ogni $t2 s per $d. Dispersione è utilizzabile quando sei stordito, impaurito o silenziato; rimuove gli effetti che limitano il movimento all'attivazione e ti rende immune a essi finché dura." },
    [425418] = { en = "Enrages you (activating abilities which require being Enraged) for $425415d  after you exceed $s1 Rage. In addition, Whirlwind also strikes with off-hand melee weapons while you are Enraged.", description = "Ti fa entrare in Furia per $425415d dopo aver superato $s1 punti furia. Inoltre, Turbine colpisce con l'arma secondaria mentre sei in Furia." },
    [425463] = { en = "Surge with fel energy, increasing your pet's and your own dodge chance by $s1%, and your chance to critically strike with all attacks by $s2%. Lasts $d.", description = "Ti avvolge di energia vil, aumentando del $s1% la probabilità di schivata tua e del famiglio e del $s2% la probabilità di colpo critico di tutti gli attacchi. Dura $d." },
    [425589] = { en = "Increases your block value by $s2% and modifies your Redoubt talent. Redoubt now also has a $m1% chance to trigger from any melee or ranged attack against you, and always triggers when you deal a melee critical strike. In addition, your Reckoning talent gains a $s3% chance per talent point to trigger from any melee or ranged attack against you.", description = "Aumenta del $s2% il valore di blocco e modifica il talento Ridotta. Ridotta ha una probabilità del $m1% di attivarsi con qualsiasi attacco in mischia o a distanza contro di te e si attiva sempre quando infliggi un colpo critico in mischia. Inoltre, Giudizio ha una probabilità del $s3% per punto talento di attivarsi con qualsiasi attacco in mischia o a distanza contro di te." },
    [425711] = { en = "A sweeping attack that strikes all enemies in front of you with your melee weapons for $s2% weapon damage. Your primary target takes $s3% increased damage.", description = "Attacco ad arco che colpisce i nemici davanti a te con le armi da mischia, infliggendo il $s2% dei danni dell'arma. Il bersaglio principale subisce il $s3% di danni aggiuntivi." },
    [425858] = { en = "When you critically heal with your Healing Wave or Lesser Healing Wave you summon an Ancestral spirit to aid you, instantly healing the lowest percentage health party member within 40 yards for $s1% of the amount healed.", description = "Quando curi criticamente con Onda di Cura o Onda di Cura Inferiore, evochi uno spirito ancestrale che cura di $s1% delle cure fornite il membro del gruppo vicino con la percentuale di salute più bassa, entro 40 m." },
    [425864] = { en = "When you critically heal with your Healing Wave or Lesser Healing Wave, you summon an Ancestral spirit to aid you, instantly healing the lowest percentage health friendly party or raid target within 40 yards.", description = "Quando curi criticamente con Onda di Cura o Onda di Cura Inferiore, evochi uno spirito ancestrale che cura il bersaglio alleato del gruppo o dell'incursione entro 40 m con la percentuale di salute più bassa." },
    [426157] = { en = "Increases all Holy damage you deal by $m1%, and your melee and spell critical strikes reduce the remaining cooldown on your Exorcism spell by ${$m2/-1000} sec.", description = "Aumenta del $m1% tutti i danni sacri inflitti; i colpi critici in mischia e con incantesimi riducono di ${$m2/-1000} s il tempo di recupero di Esorcismo." },
    [426173] = { en = "Increases the range on your Judgement by $s1 yards and your spell hit with all spells by $s2%.", description = "Aumenta di $s1 m la portata di Giudizio e del $s2% la probabilità di colpire con gli incantesimi." },
    [426195] = { en = "When activated, this ability temporarily grants you a $s1% increase to your maximum health for $d. After the effect expires, the health is lost. Additionally, while in Metamorphosis, Vengeance causes your wings to slow your falling speed.", description = "Quando attivata, aumenta temporaneamente del $s1% la salute massima per $d. Al termine dell'effetto, la salute aggiuntiva si perde. In Metamorfosi, Vendetta rallenta la caduta grazie alle tue ali." },
    [426243] = { en = "Applying Corruption, Immolate, Curse of Agony, Unstable Affliction, Shadowflame, or Siphon Life will cause you to deal instant damage to the target equal to one tick of the spell's periodic damage. Refreshing any of those spells when it has less than $s1 seconds duration remaining will cause you to deal instant damage to the target equal to the spell's remaining periodic damage.", description = "Lanciare Corruzione, Immolazione, Maledizione dell'Agonia, Afflizione Instabile, Fiamma d'Ombra o Prosciugamento Vitale infligge al bersaglio danni istantanei pari a un impulso periodico dell'incantesimo. Rinnovare uno di questi effetti quando restano meno di $s1 s ne infligge istantaneamente i danni periodici rimanenti." },
    [426301] = { en = "Damage done by you or your summoned demon has a $h% chance to increase the damage done by the other by $426303s1% for $426303d.", description = "I danni inflitti da te o dal tuo demone evocato hanno una probabilità del $h% di aumentare del $426303s1% i danni dell'altro per $426303d." },
    [426311] = { en = "Increases all Fire damage done by $s1%.", description = "Aumenta del $s1% tutti i danni da fuoco inflitti." },
    [426316] = { en = "Hitting an enemy with Conflagrate increases all Shadow damage you deal by $m3% for $1293816d, and hitting an enemy with Shadowburn increases all Fire damage you deal by $m4% for $426311d. In addition, Conflagrate has a $m2% chance not to consume Immolate, and Shadowburn has a $m2% chance to instantly refund a Soul Shard.", description = "Colpire un nemico con Conflagrazione aumenta del $m3% per $1293816d i danni da ombra; colpirlo con Bruciatura dell'Anima aumenta del $m4% per $426311d i danni da fuoco. Conflagrazione ha una probabilità del $m2% di non consumare Immolazione e Bruciatura dell'Anima una probabilità del $m2% di restituire subito un Frammento d'Anima." },
    [426940] = { en = "Go on a rampage, increasing your attack power by $s1% for $d.  This ability can only be used while Enraged.", description = "Ti lanci in una furia devastante, aumentando del $s1% la potenza d'attacco per $d. Utilizzabile solo mentre sei in Furia." },
}

for id, value in pairs(entries) do
    ns.data.spellDescriptionOverrides[id] = value
end
